import{z as l,x as i,o as B,c as n,q as e,j as A,D as a,d as o,s as r,S as s}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"postmortem 文化与案例","description":"","frontmatter":{"title":"postmortem 文化与案例","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/obs-postmortem-culture.md","filePath":"cs/obs-postmortem-culture.md","lastUpdated":1791413859000}'),p={name:"cs/obs-postmortem-culture.md"};function m(d,E,u,_,c,h){const t=i("Mermaid");return B(),n("div",null,[E[2]||(E[2]=e('<h1 id="postmortem-文化与案例" tabindex="-1">postmortem 文化与案例 <a class="header-anchor" href="#postmortem-文化与案例" aria-label="Permalink to &quot;postmortem 文化与案例&quot;">​</a></h1><div class="epigraph"><p>复盘的目的不是找出谁犯错，是找出系统哪里让聪明人合理地犯了错；一旦写复盘等于定罪，下一个操作员会学会瞒报。</p><footer>—— 据 Google SRE 书第 15 章 Postmortem Culture；Allspaw 的 Just Culture 实践（Etsy，2012）整理</footer></div><p><a href="/cs/obs-incident-command">上一课</a>的记录者写下了时间线，事故稳定、服务恢复。缺口在此时打开：事故此刻仍只是一笔损失；只有写成复盘、落地改进项，它才变成组织的资产。本课写复盘的模板与模板之上的文化：无指责为什么是技术前提而非道德姿态，各栏为什么长成那样，以及复盘文化常见的死法。本课程倒数第二课，后课收束默认已读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>复盘有四个工程缺口。其一，时间线是决策序列，不是事件流水：每一步要写「当时知道什么、据此做了什么判断」，只写「15:42 重启了实例」的读者只剩指责可做。其二，根因的单因谬误：生产事故几乎总是多重巧合——一个变更、一处缺失的防御、一条迟到的告警、一位当夜的值班——复盘只写「根因：配置错误」，其余防线的改进机会全部流失。其三，改进项不落地：没有负责人、没有期限、没有验证方式，与功能发布抢优先级必输，复盘退化成文比赛。其四，也是最致命的：指责文化。写复盘的人被问责，下一次事故的第一反应就是掩盖——数据的完整性从源头损坏，所有下游分析全部失真。</p><h3 id="无指责是信息论要求" tabindex="-1">无指责是信息论要求 <a class="header-anchor" href="#无指责是信息论要求" aria-label="Permalink to &quot;无指责是信息论要求&quot;">​</a></h3><p>把复盘想成一次测量：它测的是「决策时组织拥有什么信息」。若记录者预期被追责，测量值会系统性向「我按流程做了」偏移；而事故的漏洞恰恰常在流程外。所以无指责不是温情，是保证测量不被污染的技术条件——损失的不是礼貌，是数据。</p>',7)),(B(),A(s,null,{default:a(()=>[r(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E4%BA%8B%E6%95%85%E7%A8%B3%E5%AE%9A%22%5D%20--%3E%20PM%5B%22%E6%97%A0%E6%8C%87%E8%B4%A3%E5%A4%8D%E7%9B%98%22%5D%0A%20%20PM%20--%3E%20TL%5B%22%E6%97%B6%E9%97%B4%E7%BA%BF%EF%BC%9A%E5%86%B3%E7%AD%96%E5%8A%A0%E4%BF%A1%E6%81%AF%E7%8A%B6%E6%80%81%22%5D%0A%20%20PM%20--%3E%20CA%5B%22%E5%A4%9A%E9%87%8D%E8%B4%A1%E7%8C%AE%E5%9B%A0%E5%88%86%E6%9E%90%22%5D%0A%20%20TL%20--%3E%20AC%5B%22%E6%94%B9%E8%BF%9B%E9%A1%B9%EF%BC%9A%E8%B4%9F%E8%B4%A3%E4%BA%BA%2B%E6%9C%9F%E9%99%90%2B%E9%AA%8C%E8%AF%81%22%5D%0A%20%20CA%20--%3E%20AC%0A%20%20AC%20--%3E%20SYS%5B%22%E9%98%B2%E5%BE%A1%E5%86%99%E8%BF%9B%E7%B3%BB%E7%BB%9F%EF%BC%9A%E5%91%8A%E8%AD%A6%E3%80%81%E9%A2%84%E6%A3%80%E3%80%81%E6%B5%8B%E8%AF%95%22%5D%0A%20%20SYS%20--%3E%20NEXT%5B%22%E5%90%8C%E7%B1%BB%E4%BA%8B%E6%95%85%E6%A6%82%E7%8E%87%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p><span class="marginnote">5 Whys 源自丰田生产方式。它停在哪决定改进空间：追「为什么人犯错」五层常落到「粗心」；追「为什么系统允许这个错误直达用户」才落到设计。同一个事故，落点不同，改进项完全不同。</span></p><p><span class="marginnote">直觉类比：无指责复盘像航空业的黑匣子调查——目的不是惩罚飞行员，是找出让合格飞行员也会犯错的系统漏洞。一旦调查等于定罪，驾驶舱里的话就再也不会被如实说出，黑匣子从此只录套话。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模板五栏。影响面：用户数、时长、收入口径，直接引用 SLO 预算账本的消耗数——上一课的严重度分级用的就是这份账。时间线：检测、响应、恢复三段，带决策与信息状态。原因分析：写多重贡献因，可以追问但要止步于系统。改进项：每条四件——负责人、期限、验证方式、以及它防的是哪一类事故而不是哪一次。教训：写进 runbook、告警阈值、测试与预检的具体条目。流程上再钉两条：评审把单点事故升维成系统清单——同一服务第三次出同类事故，说明上一轮改进项没防住「类」，要回炉；复盘归档要可检索，负结果可检索，组织才没有幸存者偏差。做得对的动作同样入档：止损成功的路径要固化成 runbook，只记失败会让语料只剩负样本。</p><p><span class="marginnote">常见误区：初学者把复盘写成「根因：配置错误」一行就收工。生产事故几乎都是多重巧合——一个变更、一处缺失的防御、一条迟到的告警；单因叙事让链上每个环节的改进机会全部流失，同类事故换个马甲再来一次。</span></p>',5)),(B(),A(s,null,{default:a(()=>[r(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E4%BA%8B%E6%95%85%20%E9%85%8D%E7%BD%AE%E9%94%99%E8%AF%AF%E7%9B%B4%E8%BE%BE%E7%94%A8%E6%88%B7%22%5D%20--%3E%20A%5B%22%E9%97%AE%E6%B3%95%E4%B8%80%20%E4%B8%BA%E4%BB%80%E4%B9%88%E8%BF%99%E4%B8%AA%E4%BA%BA%E7%8A%AF%E9%94%99%22%5D%0A%20%20A%20--%3E%20B%5B%22%E8%90%BD%E5%88%B0%20%E7%B2%97%E5%BF%83%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%94%B9%E8%BF%9B%E6%98%AF%E6%89%B9%E8%AF%84%E4%B8%8E%E5%9F%B9%E8%AE%AD%20%E5%90%8C%E7%B1%BB%E6%A6%82%E7%8E%87%E4%B8%8D%E5%8F%98%22%5D%0A%20%20INC%20--%3E%20D%5B%22%E9%97%AE%E6%B3%95%E4%BA%8C%20%E4%B8%BA%E4%BB%80%E4%B9%88%E7%B3%BB%E7%BB%9F%E5%85%81%E8%AE%B8%E9%94%99%E8%AF%AF%E7%9B%B4%E8%BE%BE%E7%94%A8%E6%88%B7%22%5D%0A%20%20D%20--%3E%20E%5B%22%E8%90%BD%E5%88%B0%20%E7%BC%BA%E9%A2%84%E6%A3%80%E4%B8%8E%E5%91%8A%E8%AD%A6%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%94%B9%E8%BF%9B%E6%98%AF%E5%8A%A0%E9%A2%84%E6%A3%80%E4%B8%8E%E9%98%88%E5%80%BC%20%E6%94%B9%E5%8F%98%E6%95%85%E9%9A%9C%E5%88%86%E5%B8%83%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么改进项要防「类」不防「次」：重启那台机器不改变下次的概率，断路器、预检、阈值才改变分布——成效最终反映在错误预算消耗率的下降上，这是复盘与 SLO 工程的闭环。为什么单因叙事流行而有害：「根因」给管理者一个可交付的句子，代价是链上每个环节都被放走；多层防御要求每一层单独回答为什么没拦住。为什么复盘要写「当时知道什么」：同一个动作在信息完备与否两种状态下是两个决策；复盘读者若用后见之明评分，学到的是虚假教训。为什么文化比模板先决：模板可以被照抄，如实记录不能——它依赖「说真话无代价」的信誉积累，一次因复盘追责就会清零。</p><p><span class="marginnote">为什么重要：改进项没有负责人、期限和验证方式，就只是一句愿望——与功能发布抢排期必输，通常永远排不上。有负责人有期限的「加预检」才会在下个迭代真落地，把同类事故概率往下压。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引用具体公司的未公开事故，公开案例只取其复盘文本的口径；不写安全事件的复盘差异——法律与保密约束让那类复盘有自己的规则，归事件响应课。复盘也不是万能工具：若组织用复盘数量做考核，会催生为写而写的事故；文化指标与数量指标必须分开。事故到资产的路到此走完——下一课把整门课程收束成一张地图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>复盘的产出是资产还是损失，取决于改进项是否落地。</li><li>无指责是测量学要求：预期被追责的记录会系统性失真。</li><li>时间线记决策与信息状态，根因写多重贡献因，拒绝单因叙事。</li><li>改进项四件套：负责人、期限、验证方式、防的是类不是次。</li><li>成效回到错误预算消耗率；做得对的路径同样要固化。</li><li>出处：Google SRE 书第 15 章；Allspaw 的 Just Culture 实践（Etsy，2012）；5 Whys 源自丰田生产方式。</li></ul>',7))])}const F=l(p,[["render",m]]);export{C as __pageData,F as default};
